def removed_reason(record, now):
    """ms/mg 共用的 removed 优先级：drain（D/X）> health（unhealthy）>
    circuit（熔断非 C）> fault（D 窗口内或 F 故障相位），否则 null。"""
    if record["drain"]["state"] in ("D", "X"):
        return "drain"
